-- Proposed AdA administration example; synthetic data only. Generated by build.py.

-- Run once in a dedicated empty example database. No catalog schema or access grants are changed.

BEGIN;

CREATE SCHEMA ada_bewirtschaftung;

CREATE TABLE ada_bewirtschaftung.militaergrad (
    grad_code varchar(12) PRIMARY KEY,
    bezeichnung_de varchar(80) NOT NULL,
    gradgruppe varchar(40) NOT NULL,
    sortierung smallint NOT NULL,
    UNIQUE (sortierung),
    CHECK (sortierung >= 1)
);

CREATE TABLE ada_bewirtschaftung.personalstatus (
    status_code varchar(20) PRIMARY KEY,
    bezeichnung_de varchar(80) NOT NULL,
    aktiv boolean NOT NULL DEFAULT true
);

CREATE TABLE ada_bewirtschaftung.angehoeriger (
    ada_id uuid PRIMARY KEY,
    ada_nummer varchar(32) NOT NULL,
    vorname varchar(80) NOT NULL,
    nachname varchar(80) NOT NULL,
    geburtsdatum date NOT NULL,
    korrespondenzsprache varchar(2) NOT NULL CHECK (korrespondenzsprache IN ('de', 'fr', 'it', 'rm')),
    status_code varchar(20) NOT NULL REFERENCES ada_bewirtschaftung.personalstatus (status_code) ON DELETE RESTRICT,
    erfasst_am timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    geaendert_am timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (ada_nummer),
    CHECK (geaendert_am >= erfasst_am)
);

CREATE TABLE ada_bewirtschaftung.organisationseinheit (
    org_id uuid PRIMARY KEY,
    org_code varchar(30) NOT NULL,
    bezeichnung varchar(120) NOT NULL,
    parent_org_id uuid REFERENCES ada_bewirtschaftung.organisationseinheit (org_id) ON DELETE RESTRICT,
    gueltig_ab date NOT NULL,
    gueltig_bis date,
    UNIQUE (org_code),
    CHECK (gueltig_bis IS NULL OR gueltig_bis >= gueltig_ab),
    CHECK (parent_org_id IS NULL OR parent_org_id <> org_id)
);

CREATE TABLE ada_bewirtschaftung.einteilung (
    einteilung_id uuid PRIMARY KEY,
    ada_id uuid NOT NULL REFERENCES ada_bewirtschaftung.angehoeriger (ada_id) ON DELETE RESTRICT,
    org_id uuid NOT NULL REFERENCES ada_bewirtschaftung.organisationseinheit (org_id) ON DELETE RESTRICT,
    funktion varchar(120) NOT NULL,
    gueltig_ab date NOT NULL,
    gueltig_bis date,
    UNIQUE (ada_id, org_id, gueltig_ab),
    CHECK (gueltig_bis IS NULL OR gueltig_bis >= gueltig_ab)
);

CREATE TABLE ada_bewirtschaftung.gradverlauf (
    gradverlauf_id uuid PRIMARY KEY,
    ada_id uuid NOT NULL REFERENCES ada_bewirtschaftung.angehoeriger (ada_id) ON DELETE RESTRICT,
    grad_code varchar(12) NOT NULL REFERENCES ada_bewirtschaftung.militaergrad (grad_code) ON DELETE RESTRICT,
    gueltig_ab date NOT NULL,
    gueltig_bis date,
    UNIQUE (ada_id, gueltig_ab),
    CHECK (gueltig_bis IS NULL OR gueltig_bis >= gueltig_ab)
);

CREATE TABLE ada_bewirtschaftung.dienstleistung (
    dienst_id uuid PRIMARY KEY,
    dienst_code varchar(30) NOT NULL,
    dienst_art varchar(20) NOT NULL CHECK (dienst_art IN ('RS', 'WK', 'KURS', 'ANDERE')),
    bezeichnung varchar(120) NOT NULL,
    org_id uuid NOT NULL REFERENCES ada_bewirtschaftung.organisationseinheit (org_id) ON DELETE RESTRICT,
    beginn date NOT NULL,
    ende date NOT NULL,
    UNIQUE (dienst_code),
    CHECK (ende >= beginn)
);

CREATE TABLE ada_bewirtschaftung.aufgebot (
    aufgebot_id uuid PRIMARY KEY,
    ada_id uuid NOT NULL REFERENCES ada_bewirtschaftung.angehoeriger (ada_id) ON DELETE RESTRICT,
    dienst_id uuid NOT NULL REFERENCES ada_bewirtschaftung.dienstleistung (dienst_id) ON DELETE RESTRICT,
    ausgestellt_am date,
    status varchar(20) NOT NULL CHECK (status IN ('ENTWURF', 'VERSANDT', 'BESTAETIGT', 'ANNULLIERT')),
    erfasst_am timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (ada_id, dienst_id),
    CHECK (status = 'ENTWURF' OR ausgestellt_am IS NOT NULL)
);

CREATE TABLE ada_bewirtschaftung.dienstteilnahme (
    teilnahme_id uuid PRIMARY KEY,
    aufgebot_id uuid NOT NULL REFERENCES ada_bewirtschaftung.aufgebot (aufgebot_id) ON DELETE RESTRICT,
    eintritt date,
    austritt date,
    diensttage integer NOT NULL DEFAULT 0,
    status varchar(20) NOT NULL CHECK (status IN ('GEPLANT', 'EINGERUECKT', 'ABGESCHLOSSEN', 'NICHT_EINGERUECKT')),
    UNIQUE (aufgebot_id),
    CHECK (diensttage >= 0),
    CHECK (austritt IS NULL OR (eintritt IS NOT NULL AND austritt >= eintritt)),
    CHECK (status NOT IN ('EINGERUECKT', 'ABGESCHLOSSEN') OR eintritt IS NOT NULL),
    CHECK (status <> 'ABGESCHLOSSEN' OR austritt IS NOT NULL)
);

CREATE TABLE ada_bewirtschaftung.qualifikationstyp (
    qualifikation_code varchar(30) PRIMARY KEY,
    bezeichnung varchar(120) NOT NULL,
    beschreibung varchar(500),
    gueltigkeits_monate smallint,
    CHECK (gueltigkeits_monate IS NULL OR gueltigkeits_monate > 0)
);

CREATE TABLE ada_bewirtschaftung.qualifikation (
    qualifikation_id uuid PRIMARY KEY,
    ada_id uuid NOT NULL REFERENCES ada_bewirtschaftung.angehoeriger (ada_id) ON DELETE RESTRICT,
    qualifikation_code varchar(30) NOT NULL REFERENCES ada_bewirtschaftung.qualifikationstyp (qualifikation_code) ON DELETE RESTRICT,
    erworben_am date NOT NULL,
    gueltig_bis date,
    dienst_id uuid REFERENCES ada_bewirtschaftung.dienstleistung (dienst_id) ON DELETE RESTRICT,
    UNIQUE (ada_id, qualifikation_code, erworben_am),
    CHECK (gueltig_bis IS NULL OR gueltig_bis >= erworben_am)
);

CREATE INDEX ix_angehoeriger_status_code ON ada_bewirtschaftung.angehoeriger (status_code);

CREATE INDEX ix_organisationseinheit_parent_org_id ON ada_bewirtschaftung.organisationseinheit (parent_org_id);

CREATE INDEX ix_einteilung_ada_id ON ada_bewirtschaftung.einteilung (ada_id);

CREATE INDEX ix_einteilung_org_id ON ada_bewirtschaftung.einteilung (org_id);

CREATE INDEX ix_gradverlauf_ada_id ON ada_bewirtschaftung.gradverlauf (ada_id);

CREATE INDEX ix_gradverlauf_grad_code ON ada_bewirtschaftung.gradverlauf (grad_code);

CREATE INDEX ix_dienstleistung_org_id ON ada_bewirtschaftung.dienstleistung (org_id);

CREATE INDEX ix_aufgebot_ada_id ON ada_bewirtschaftung.aufgebot (ada_id);

CREATE INDEX ix_aufgebot_dienst_id ON ada_bewirtschaftung.aufgebot (dienst_id);

CREATE INDEX ix_dienstteilnahme_aufgebot_id ON ada_bewirtschaftung.dienstteilnahme (aufgebot_id);

CREATE INDEX ix_qualifikation_ada_id ON ada_bewirtschaftung.qualifikation (ada_id);

CREATE INDEX ix_qualifikation_qualifikation_code ON ada_bewirtschaftung.qualifikation (qualifikation_code);

CREATE INDEX ix_qualifikation_dienst_id ON ada_bewirtschaftung.qualifikation (dienst_id);

